'use strict';
const groups = [{"id": "centro", "number": "01", "title": "Centro on foot", "timing": "ANY FREE AFTERNOON · AFTER 5PM IS KINDER", "color": "pink", "description": "The main square and the three buildings around it, then north up Calle 60 from one small park to the next.", "sections": [["PLAZA GRANDE", [["cathedral", "Catedral de San Ildefonso", "finished in 1598 with stone from the Maya temples of T’hó"], ["gobierno", "Palacio de Gobierno", "Fernando Castro Pacheco’s murals of Yucatán’s history, upstairs", "Free."], ["casamontejo", "Casa de Montejo", "the conquistador family’s house from the 1540s, with its carved front", "Free museum inside."], ["walkingtour", "Guided walk of the centre", "ask at the tourist desk in the Centro Cultural Olimpo, Calle 62", "A good first afternoon."]]], ["UP CALLE 60", [["santalucia", "Parque de Santa Lucía", "arcades, restaurants and the giant white courting chairs"], ["santaana", "Parque de Santa Ana", "a small square with a market, a few blocks further north"]]]], "note": "Even-numbered streets run north to south, odd ones east to west. An address like “Calle 60 x 55 y 57” means on 60, between 55 and 57."}, {"id": "montejo", "number": "02", "title": "Paseo de Montejo", "timing": "A LATE AFTERNOON · OR SUNDAY MORNING BY BIKE", "color": "green", "description": "The pretty street from my notes: a long tree-lined avenue of mansions built with henequén money around 1900.", "sections": [["THE AVENUE", [["paseowalk", "Walk the Paseo", "from the Remate at Calle 47 north to the monument, about 2 km"], ["gemelas", "Casas Gemelas", "two matching French-style mansions", "One of them, Montejo 495, opens as a house museum."], ["biciruta", "Biciruta", "Sunday mornings the avenue closes to cars and fills with bikes", "From 8am to noon. Bikes are rented from a stand near the Monumento a la Patria."]]], ["MUSEUM & MONUMENT", [["canton", "Palacio Cantón", "the regional anthropology museum, in the grandest mansion on the avenue", "Closed on Mondays."], ["patria", "Monumento a la Patria", "Rómulo Rozo’s ring of carved stone, in the middle of a roundabout"]]]], "note": "There is little shade between the trees and it is a long walk back. Take a bus or an Uber one way."}, {"id": "evenings", "number": "03", "title": "Evenings in the squares", "timing": "AFTER DINNER · ALL FREE", "color": "blue", "description": "The city puts on something free almost every night. Each one is about an hour.", "sections": [["EARLY IN THE WEEK", [["vaqueria", "Vaquería", "Mondays, 9pm: jarana dancing with the city’s folk ballet", "Under the arches of the Palacio Municipal, on Plaza Grande."], ["videomapping", "Video mapping on Casa de Montejo", "Wednesdays, 8:30pm: the founding of the city projected on the façade"], ["serenata", "Serenata Yucateca", "Thursdays, 9pm in Parque de Santa Lucía: trova trios, poetry and dance", "It has run every week since 1965. Come half an hour early for a seat."]]], ["THE WEEKEND", [["poktapok", "Pok ta Pok", "Fridays, 8pm in front of the cathedral: the Maya ball game, played with the hips", "Some listings say Saturday. Check the week’s programme.", [["Yucatán Today · the week’s free events", "https://yucatantoday.com/en/events"]]], ["nochemexicana", "Noche Mexicana", "Saturdays, 8pm at the Remate de Paseo de Montejo: mariachi, dancing and food stalls"], ["domingo", "Mérida en Domingo", "Sundays from mid-morning on Plaza Grande: craft stalls, food and music all day", "Stay for the evening: locals dance on the square on Sunday nights."]]]], "note": "Days and venues move around. Check the Semana Meridana programme when we arrive."}, {"id": "markets", "number": "04", "title": "Markets & the Maya museum", "timing": "TWO MORNINGS · MARKETS ARE BEST EARLY", "color": "pink", "description": "The big working market, a small neighbourhood one, and the museum to see before the ruins.", "sections": [["MARKETS", [["lucasgalvez", "Mercado Lucas de Gálvez", "the main market: habaneros, spice pastes called recados, fruit and hammocks", "Hot and crowded by late morning. Carry small notes."], ["santiago", "Mercado de Santiago", "a small market on a pretty square, west of the centre", "Known for its breakfast stalls."]]], ["MUSEUM", [["granmuseo", "Gran Museo del Mundo Maya", "the big modern Maya museum on the north side of the city", "Closed on Tuesdays. A bus or Uber ride from the centre. Best before Chichén Itzá and Uxmal."]]]], "note": "Several museums close on Mondays, and the Gran Museo on Tuesdays."}, {"id": "work", "number": "05", "title": "Desk days", "timing": "WEEKDAY MORNINGS", "color": "blue", "description": "One coworking space in the centre and two cafés people work from.", "sections": [["COWORKING", [["conexion60", "Conexión60", "in the Paseo 60 complex, Calle 60 no. 346, on the third and fourth floors", "Day pass about 200–220 pesos, roughly 8am–6pm. Part indoors, part open-air."]]], ["CAFÉS WITH WIFI", [["voltacafe", "Voltacafé", "big tables and fast wifi"], ["estacion72", "Estación 72", "a relaxed café with good wifi"]]]], "note": "Coworking and cafés don’t count towards progress: tick them if you like."}, {"id": "food", "number": "06", "title": "Food & drinks", "timing": "WHENEVER WE’RE HUNGRY", "color": "green", "description": "The Yucatán bucket list, my old notes and the two restaurants saved on my map.", "sections": [["YUCATECAN", [["cochinita", "Cochinita pibil", "pork in achiote and sour orange, slow-cooked in a pit; eaten in tacos and tortas", "A weekend breakfast here: market stalls sell out by late morning."], ["trapiche", "El Trapiche", "from my notes: typical Yucatecan food near the main square"], ["chayamaya", "La Chaya Maya", "the classic place for the whole regional menu"], ["yucatanlist", "The rest of the list", "sopa de lima, panuchos, salbutes, papadzules, poc chuc and queso relleno"]]], ["SAVED ON MY MAP", [["huniik", "Huniik", "Calle 60 between 45 and 47, by Santa Ana: a small tasting-menu restaurant", "Needs a reservation."], ["mora", "MORA", "Indian restaurant in San Carlos, in the north of the city", "A taxi ride from the centre."]]], ["SWEET & COLD", [["colon", "Sorbetería Colón", "from my notes: sorbets and ice cream since 1907", "On Paseo de Montejo and on Plaza Grande."], ["marquesitas", "Marquesitas", "a crisp rolled wafer filled with Edam cheese, from the evening carts"], ["limonada", "Limonada de coco", "the one with question marks on my list"], ["manifesto", "Manifesto", "coffee roasters"], ["bengala", "Bengala Kaffeehaus", "coffee near Santa Lucía"]]]], "note": "Food and drinks don’t count towards progress."}, {"id": "uxmal", "number": "SAT", "title": "Uxmal", "timing": "OUR FIRST SATURDAY · BACK BY LATE AFTERNOON", "color": "pink", "weekend": true, "description": "The other great Maya city, about 80 km south, with far fewer people. The carving here is finer than at Chichén Itzá.", "table": {"caption": "How to get to Uxmal", "map": "Map", "days": [["Bus · Uxmal only", [["About 1.5 hours", "Bus from the TAME terminal", "Calle 69 between 68 and 70. Morning departures at about 6am, 9am and noon; buses back at about 3pm and 5pm. Confirm at the terminal the day before.", "It stops on the road by the entrance", "Uxmal"]]], ["Car or driver · with a cenote", [["All day", "Uxmal, then Cenote X’batun", "X’batun is saved on my map: an open cenote near San Antonio Mulix, off the same road back. No bus goes there, so this needs a hire car or a driver for the day.", "About 1 hour 15 from Mérida", "Cenote X’batun"]]]]}, "sections": [["PYRAMID & QUADRANGLE", [["adivino", "Pirámide del Adivino", "the Pyramid of the Magician: rounded sides, straight ahead as you walk in", "No climbing."], ["monjas", "Cuadrángulo de las Monjas", "four long buildings around a courtyard, covered in stone mosaic"]]], ["HIGHER GROUND", [["gobernador", "Palacio del Gobernador", "a façade nearly 100 m long, on its own platform"], ["granpiramide", "La Gran Pirámide", "the one you can still climb, by the north stair", "The view takes in the whole site."]]]], "note": "Entry is two tickets at two windows. Sources give anything from 500 to 720 pesos for foreigners in 2026, so bring 750 each in cash. Open from 8am; last entry around 4pm. The evening light show is suspended.", "link": ["Yucatán Today · Uxmal", "https://yucatantoday.com/en/blog/uxmal"]}, {"id": "cenotes", "number": "SAT", "title": "A day of cenotes", "timing": "OUR SECOND SATURDAY · SWIMMING ALL DAY", "color": "green", "weekend": true, "description": "The full cenote day. Three ways to do it, all about an hour south-east of Mérida around Cuzamá and Homún.", "table": {"caption": "Three ways to do the cenotes", "map": "Map", "days": [["Cuzamá", [["2–3 hours there", "By horse-drawn cart", "The classic: a cart on old narrow rails takes us to three cenotes and waits while we swim. Priced per cart, so the same for two as for four.", "Colectivo from Calle 67 between 50 and 52", "Cuzamá Yucatán"]]], ["Homún", [["As long as we like", "By mototaxi", "The village next door has more cenotes to choose from. A mototaxi driver takes us round for a fixed price and each cenote charges a small entry.", "Colectivo from the same corner", "Homún Yucatán"]]], ["Santa Bárbara", [["About 3 hours there", "One ticket, three cenotes", "The organised version, in Homún: three cenotes on one ticket, reached by cart or bike, with showers and a restaurant on site.", "In Homún", "Cenotes Santa Bárbara Homún"]]]]}, "sections": [["GETTING AROUND", [["cenoteride", "The ride between cenotes", "by horse cart, mototaxi or bike, depending on which we pick"]]], ["IN THE WATER", [["cenoteswim", "Swim in three cenotes", "some open to the sky, some inside caves reached by steep stairs", "Bring swimwear, a towel, water shoes and cash. No sunscreen in the water."]]]], "note": "I haven’t confirmed current prices for any of the three. The last colectivos back leave mid-afternoon, so start early.", "link": ["Along Dusty Roads · Mérida", "https://www.alongdustyroads.com/posts/2014/4/11/city-guides-merida-mexico"]}, {"id": "chichen", "number": "TUE", "title": "Chichén Itzá & Valladolid", "timing": "A TUESDAY OFF · DANIELE’S BIRTHDAY", "color": "blue", "weekend": true, "description": "The birthday trip: the famous ruins in the morning, then lunch and the afternoon in the small colonial town 40 km further on.", "table": {"caption": "How the day runs", "map": "Map", "days": [["By bus", [["About 2 hours", "ADO bus from Mérida", "Departures at about 7, 9 and 11am. Roughly 280–320 pesos each way; cheaper bought a few days ahead at the terminal. Take the 7am.", "It stops at the site entrance", "Chichén Itzá"], ["About 45 minutes", "Colectivo to Valladolid", "Shared vans run from the ruins to Valladolid for about 40 pesos and stop a block from the bus station.", "From the road outside the site", "Valladolid Yucatán"], ["About 2 hours 15", "ADO back to Mérida", "Buses run into the evening. Buy the return ticket on arrival in Valladolid.", "From the ADO station in Valladolid", "ADO Valladolid Yucatán"]]], ["Car or driver", [["All day", "Hire car or a driver", "The same day with no timetable: about 1.5 hours to the ruins on the toll road, 40 minutes on to Valladolid and under 2 hours back.", "From Mérida", "Chichén Itzá"]]]]}, "sections": [["THE RUINS", [["castillo", "El Castillo", "the pyramid of Kukulcán: 365 steps, one for each day of the year", "No climbing."], ["ballcourt", "The Great Ball Court", "the largest in Mesoamerica; a clap echoes from end to end"], ["sacredcenote", "The Sacred Cenote", "at the end of a raised white road; for offerings, not for swimming"], ["caracol", "El Caracol", "the round observatory"]]], ["VALLADOLID", [["vplaza", "The main square & San Servacio", "palms, white courting chairs and the twin-towered church"], ["frailes", "Calzada de los Frailes", "the prettiest street: painted houses and small shops, leading to the convent"], ["sanbernardino", "Convento de San Bernardino", "a fortress-like Franciscan convent from the 1550s"], ["lomitos", "Lunch: lomitos de Valladolid", "the town’s own dish, pork in tomato sauce; the longaniza sausage is local too"]]]], "note": "Entry to Chichén Itzá is 697 pesos each for foreigners in 2026, paid as two tickets at two windows. Open 8am–5pm, last entry at 4pm. Hat, water and cash."}];

const optional = [["celestun", "Celestún", "a boat through the mangroves to the flamingos, about 1.5 hours west", "On our weekend list. Flamingo numbers build from December to March. Boats are priced per boat, so sharing helps: tours ask for about 500 pesos each in cash. Buses leave the Noreste terminal roughly every hour.", [["Yucatán Today · Celestún", "https://yucatantoday.com/en/celestun"]]], ["elcuyo", "El Cuyo", "a beach village on the north coast: wide sand, kitesurfers and flamingos nearby", "On our weekend list, but far: about 3.5 hours by car, longer by bus with a change in Tizimín. It needs a night or two, so it would take a whole weekend.", [["Yucatán Today · El Cuyo", "https://yucatantoday.com/en/blog/el-cuyo"]]], ["xbatun", "Cenote X’batun", "saved on my map: an open cenote near San Antonio Mulix, south of the city", "Easiest with a car, on the way back from Uxmal."], ["ikkil", "Cenote Ik Kil", "the open cenote 3 km from Chichén Itzá, with vines hanging to the water", "Only if we want a swim on the birthday: a 10-minute taxi from the ruins, and it would shorten Valladolid."], ["zaci", "Cenote Zací", "a cenote in the middle of Valladolid, a few blocks from the square", "For a quick dip on the birthday. Check it is open first."], ["izamal", "Izamal", "the town painted yellow, with a convent built on a Maya platform; about 1 hour 15 east"], ["progreso", "Progreso", "the nearest beach, with a very long pier; under an hour north by bus"], ["campeche", "Campeche", "saved on my map: a walled port of pastel houses, about 2.5 hours by bus"]];
const KEY='frolicking-nicky-merida-v1';
let checked={}; let storageOK=true;
try { const saved=JSON.parse(localStorage.getItem(KEY)||'{}'); if(saved && typeof saved==='object' && !Array.isArray(saved)) checked=saved; } catch {storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const OPTIONAL_IDS=new Set(["conexion60", "voltacafe", "estacion72", "cochinita", "trapiche", "chayamaya", "yucatanlist", "huniik", "mora", "colon", "marquesitas", "limonada", "manifesto", "bengala", "lomitos"]);
const countedIds=()=>groups.filter(()=>true).flatMap(g=>g.sections.flatMap(s=>s[1].map(r=>r[0]))).filter(id=>!OPTIONAL_IDS.has(id));
function item(row,extra=false) {const [id,title,desc,note,links]=row;return `<label class="task${checked[id]===true?' completed':''}"><input type="checkbox" id="${esc(id)}" data-extra="${extra}" ${checked[id]===true?'checked':''}><span class="checkmark" aria-hidden="true"></span><span class="task-copy"><span class="task-title">${esc(title)}</span> <span class="specialty">(${esc(desc)})</span>${note?`<span class="task-note">${esc(note)}</span>`:''}${links&&links.length?`<span class="fn-task-links">${links.map(([l,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(l)} ↗︎</a>`).join('')}</span>`:''}</span></label>`;}
const PHOTOS={"centro": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Palacio_de_Gobierno_del_Estado_de_Yucat%C3%A1n_01.jpg/1280px-Palacio_de_Gobierno_del_Estado_de_Yucat%C3%A1n_01.jpg", "The green arcaded courtyard of the Palacio de Gobierno in Mérida", 1280, 853, "ProtoplasmaKid", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Palacio_de_Gobierno_del_Estado_de_Yucat%C3%A1n_01.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Portales_del_Parque_de_Santa_Luc%C3%ADa_en_M%C3%A9rida%2C_Yucat%C3%A1n_%2801%29.jpg/1280px-Portales_del_Parque_de_Santa_Luc%C3%ADa_en_M%C3%A9rida%2C_Yucat%C3%A1n_%2801%29.jpg", "The arcades along Parque de Santa Lucía in Mérida", 1280, 960, "Inri", "CC0", "https://commons.wikimedia.org/wiki/File:Portales_del_Parque_de_Santa_Luc%C3%ADa_en_M%C3%A9rida,_Yucat%C3%A1n_(01).jpg"]]], "montejo": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Casas_C%C3%A1mara%2C_Casa_del_Minarete_-_Axtel_-_Paseo_de_Montejo%2C_M%C3%A9rida%2C_Yucat%C3%A1n.jpg/1280px-Casas_C%C3%A1mara%2C_Casa_del_Minarete_-_Axtel_-_Paseo_de_Montejo%2C_M%C3%A9rida%2C_Yucat%C3%A1n.jpg", "The twin French-style mansions on Paseo de Montejo", 1280, 857, "Andreita Pech", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Casas_C%C3%A1mara,_Casa_del_Minarete_-_Axtel_-_Paseo_de_Montejo,_M%C3%A9rida,_Yucat%C3%A1n.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Monumento_a_la_Patria%2C_M%C3%A9rida_Yucatan_Mexico_2018.jpg/1280px-Monumento_a_la_Patria%2C_M%C3%A9rida_Yucatan_Mexico_2018.jpg", "The carved stone Monumento a la Patria on its roundabout", 1280, 960, "amanderson2", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Monumento_a_la_Patria,_M%C3%A9rida_Yucatan_Mexico_2018.jpg"]]], "evenings": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Bailando_la_Jarana_-_Plaza_Grande%2C_M%C3%A9rida%2C_Yucat%C3%A1n_Dic_2019.jpg/1280px-Bailando_la_Jarana_-_Plaza_Grande%2C_M%C3%A9rida%2C_Yucat%C3%A1n_Dic_2019.jpg", "Dancers in white embroidered dress dancing the jarana under the arches of Plaza Grande", 1280, 853, "Bruno Rijsman", "CC BY-SA 2.0", "https://commons.wikimedia.org/wiki/File:Bailando_la_Jarana_-_Plaza_Grande,_M%C3%A9rida,_Yucat%C3%A1n_Dic_2019.jpg"]]], "chichen": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Chichen-Itza-Castillo-Seen-From-East.JPG/1280px-Chichen-Itza-Castillo-Seen-From-East.JPG", "El Castillo, the stepped pyramid at Chichén Itzá, under a cloudy sky", 1280, 960, "Bjørn Christian Tørrissen", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Chichen-Itza-Castillo-Seen-From-East.JPG"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Valladolid_calle.jpg/1280px-Valladolid_calle.jpg", "A street of painted houses in Valladolid", 1280, 847, "Haakon S. Krohn", "CC BY 4.0", "https://commons.wikimedia.org/wiki/File:Valladolid_calle.jpg"], ["https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Iglesia_de_San_Servacio%2C_Valladolid%2C_Yucatan%2C_Mexico_Marzo_2021.jpg/1280px-Iglesia_de_San_Servacio%2C_Valladolid%2C_Yucatan%2C_Mexico_Marzo_2021.jpg", "The church of San Servacio behind the palms of Valladolid’s main square", 1280, 960, "Sharon Hahn Darlin", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Iglesia_de_San_Servacio,_Valladolid,_Yucatan,_Mexico_Marzo_2021.jpg"]]], "uxmal": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Pyramid_of_the_Magician_%28Pir%C3%A1mide_del_Adivino%29%2C_Zona_Arqueol%C3%B3gica_de_Uxmal%2C_Yucatan%2C_Mexico.jpg/1280px-Pyramid_of_the_Magician_%28Pir%C3%A1mide_del_Adivino%29%2C_Zona_Arqueol%C3%B3gica_de_Uxmal%2C_Yucatan%2C_Mexico.jpg", "The rounded Pyramid of the Magician at Uxmal, framed by branches", 1280, 960, "Sharon Hahn Darlin", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Pyramid_of_the_Magician_(Pir%C3%A1mide_del_Adivino),_Zona_Arqueol%C3%B3gica_de_Uxmal,_Yucatan,_Mexico.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Nunnery_Quadrangle%2C_Uxmal_Maya_site%2C_Yucatan%2C_June_2024.jpg/1280px-Nunnery_Quadrangle%2C_Uxmal_Maya_site%2C_Yucatan%2C_June_2024.jpg", "The long carved buildings of the Nunnery Quadrangle at Uxmal", 1280, 720, "Eden, Janine and Jim", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Nunnery_Quadrangle,_Uxmal_Maya_site,_Yucatan,_June_2024.jpg"]]], "cenotes": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Truk%2C_Cenotes%2C_Cuzam%C3%A1_-_Tranvias_de_Caballo.jpg/1280px-Truk%2C_Cenotes%2C_Cuzam%C3%A1_-_Tranvias_de_Caballo.jpg", "A horse pulling a small cart along narrow rails to the cenotes of Cuzamá", 1280, 853, "Gildardo Sánchez", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Truk,_Cenotes,_Cuzam%C3%A1_-_Tranvias_de_Caballo.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Cenote_en_Yucat%C3%A1n.jpg/1280px-Cenote_en_Yucat%C3%A1n.jpg", "Tree roots reaching down to the blue water of a cenote", 1280, 960, "Andrea 4164", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Cenote_en_Yucat%C3%A1n.jpg"]]]};
const fig=([src,alt,w,h,by,lic,url])=>`<figure class="fn-v-photo"><a href="${src}" target="_blank" rel="noopener"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></a></figure>`;
const muertosTable=(t,gid)=>{const pick=0;return `<div class="fn-plan-tabs" role="tablist" aria-label="${esc(t.caption)}">${t.days.map(([day],i)=>`<button type="button" role="tab" id="fn-plan-tab-${gid}-${i}" aria-controls="fn-plan-day-${gid}-${i}" aria-selected="${i===pick}" tabindex="${i===pick?0:-1}">${esc(day.split(' · ')[0])}</button>`).join('')}</div>${t.days.map(([day,rows],i)=>`<div class="fn-plan-panel" role="tabpanel" id="fn-plan-day-${gid}-${i}" aria-labelledby="fn-plan-tab-${gid}-${i}"${i===pick?'':' hidden'}>${day.includes(' · ')?`<p class="fn-plan-sub">${esc(day.split(' · ').slice(1).join(' · '))}</p>`:''}<ol class="fn-plan-stops">${rows.map(([when,plan,what,where,q,url])=>`<li${/★/.test(plan)?' class="fn-plan-star"':''}><span class="fn-plan-when">${esc(when)}</span><div><p class="fn-plan-name">${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(plan)} ↗︎</a>`:esc(plan)}</p><p class="fn-plan-what">${esc(what)}</p><p class="fn-plan-where">${esc(where)} <a class="fn-plan-map" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(q)}" target="_blank" rel="noopener noreferrer">${esc(t.map)}</a></p></div></li>`).join('')}</ol></div>`).join('')}`;};
let rowN=0;
document.querySelector('#itinerary').innerHTML=groups.map(g=>`<section id="${g.id}" class="outing fn-split ${g.color} ${g.weekend?'weekend':''}" aria-labelledby="title-${g.id}"><div class="outing-heading"><span class="number" aria-hidden="true">${g.number}</span><div><p class="eyebrow">${g.timing}</p><h2 id="title-${g.id}">${g.title}</h2><p class="section-desc">${g.description}</p></div><span class="group-count" id="count-${g.id}" aria-label="Section completion"></span></div>${g.table?`<div class="fn-plan-wrap">${muertosTable(g.table,g.id)}</div>`:''}<div class="outing-body fn-split-body"${g.sections.length?'':' hidden'}>${g.sections.map(([title,rows],si)=>{const ps=(PHOTOS[g.id]||[])[si]||[];const card=`<div class="task-group"><h3>${title}</h3>${rows.map(r=>item(r,OPTIONAL_IDS.has(r[0]))).join('')}</div>`;return ps.length?`<div class="fn-v-row${rowN++%2?' fn-v-rev':''}"><div class="fn-v-side">${ps.map(fig).join('')}</div>${card}</div>`:card;}).join('')}</div><div class="outing-note"><p>${g.note}</p>${g.link?`<a href="${g.link[1]}" target="_blank" rel="noopener noreferrer">${g.link[0]} ↗︎</a>`:''}</div></section>`).join('');
document.querySelectorAll('.fn-plan-tabs').forEach(list=>{const tabs=[...list.querySelectorAll('[role=tab]')];const show=(tab,focus)=>{tabs.forEach(b=>{const on=b===tab;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;document.getElementById(b.getAttribute('aria-controls')).hidden=!on;});if(focus)tab.focus();};tabs.forEach((b,i)=>{b.addEventListener('click',()=>show(b));b.addEventListener('keydown',e=>{const n={ArrowRight:i+1,ArrowLeft:i-1,Home:0,End:tabs.length-1}[e.key];if(n===undefined)return;e.preventDefault();show(tabs[(n+tabs.length)%tabs.length],true);});});});
document.querySelector('#optional-list').innerHTML=optional.map(r=>item(r,true)).join('');
function update(announce=false){const mainIds=countedIds();const done=mainIds.filter(id=>checked[id]===true).length;const percent=Math.round(done/mainIds.length*100);document.querySelector('#progress-count').textContent=done;document.querySelector('#progress-total').textContent=`of ${mainIds.length} places & moments`;document.querySelector('#percent').textContent=percent+'%';document.querySelector('#progress').value=percent;document.querySelector('#progress').textContent=percent+'%';groups.forEach(g=>{const inactive=false;const ids=g.sections.flatMap(s=>s[1].map(r=>r[0])).filter(id=>!OPTIONAL_IDS.has(id));document.querySelector('#count-'+g.id).hidden=!ids.length;document.querySelector('#count-'+g.id).textContent=inactive?"Alternative: excluded from checklist":`${ids.filter(id=>checked[id]===true).length} / ${ids.length}`;});const extra=[...optional.map(r=>r[0]),...OPTIONAL_IDS].filter(id=>checked[id]===true).length;document.querySelector('#extra-count').textContent=`${extra} optional ${extra===1?'stop':'stops'} done`;document.querySelector('#save-note').textContent=storageOK?'Progress saved on this device.':'Progress works here, but saving is unavailable in this browser.';if(announce)document.querySelector('#announcement').textContent=`${done} of ${mainIds.length} main items complete. ${extra} optional stops done.`;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(checked));storageOK=true;}catch{storageOK=false;}}
document.addEventListener('change',e=>{if(!e.target.matches('.task input'))return;checked[e.target.id]=e.target.checked;e.target.closest('.task').classList.toggle('completed',e.target.checked);persist();update(true);});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const next=JSON.parse(e.newValue||'{}');checked=next&&typeof next==='object'&&!Array.isArray(next)?next:{};}catch{checked={};}document.querySelectorAll('.task input').forEach(el=>{el.checked=checked[el.id]===true;el.closest('.task').classList.toggle('completed',el.checked);});update();});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-reset').addEventListener('click',()=>dialog.close());document.querySelector('#confirm-reset').addEventListener('click',()=>{checked={};persist();document.querySelectorAll('.task input').forEach(el=>{el.checked=false;el.closest('.task').classList.remove('completed');});update(true);dialog.close();});
update();
